"use strict";
let deskEntered=false,phonePickerFilter='all',qqChat=null,qqMessages={},monoCalcValue='0',monoCalcLeft=null,monoCalcOperation=null,monoCalcFresh=true;
const monoApps=['home','sms','contacts','snake','calculator'];
const qqFriends=[{id:'summer',name:'小夏',face:'夏',status:'在线',sign:'放学以后，老地方见。',reply:'我在呢，刚刚还在翻那本旧杂志。'},{id:'breeze',name:'晚风',face:'风',status:'在线',sign:'慢一点，上网。',reply:'收到啦。今天想听什么歌？'},{id:'desk',name:'同桌',face:'同',status:'离开',sign:'正在写作业…',reply:'等我写完这道题，晚点聊。'}];
try{const saved=JSON.parse(localStorage.getItem('olddays-qq-demo')||'{}');for(const f of qqFriends)if(Array.isArray(saved[f.id]))qqMessages[f.id]=saved[f.id].filter(m=>m&&typeof m.text==='string'&&['me','friend'].includes(m.from)).slice(-20).map(m=>({from:m.from,text:m.text.slice(0,120)}));}catch{}
function isTextOnlyPhone(){return ['nokia3310','nokia1100'].includes(phoneState.model);}
function phoneAppAllowed(app){return !isTextOnlyPhone()||monoApps.includes(app);}
function renderPhoneEntrance(){const groups=[['all','所有手机'],['keys','实体按键'],['touch','触屏时代'],['full','全面屏']];return `<section class="phone-entrance"><header><small>OLDDAYS / ${date.replaceAll('-',' / ')} / 选一部手机</small><h1>今天，想把哪一部<br>旧手机握回手里？</h1><p>黑白屏、塞班、翻盖、触屏与全面屏。<br>每一部手机，都有属于自己的功能。</p></header><nav>${groups.map(([id,t])=>`<button data-phone-picker-filter="${id}" aria-pressed="${phonePickerFilter===id}">${t}</button>`).join('')}</nav><div class="phone-choice-grid">${Object.entries(phoneModels).filter(([id])=>phonePickerFilter==='all'||(phonePickerFilter==='full'?id==='fullscreen':phonePickerFilter==='touch'?['nokia5230','n97','iphone'].includes(id):!['fullscreen','nokia5230','n97','iphone'].includes(id))).map(([id,m])=>`<button class="phone-choice-card" data-choose-phone="${id}"><div class="mini-phone mini-${m.class.split(' ')[0]} ${id==='fullscreen'?'mini-fullscreen':''}"><i></i><div><b>${['nokia3310','nokia1100'].includes(id)?'▂▄▆':'20:04'}</b><span>${['nokia3310','nokia1100'].includes(id)?'NOKIA':'▣　✉　♪'}</span></div><em>•••<br>•••<br>•••</em></div><small>${m.era}</small><h2>${escapeHTML(m.name.replace(' 风格',''))}</h2><p>${['nokia3310','nokia1100'].includes(id)?'短信 / 通讯录 / 原生小游戏':id==='fullscreen'?'全面屏触控 / 应用 / 影音 / 漫画':'UC / QQ / 掌上音乐 / 掌上杂志'}</p><span class="phone-choice-enter">拿起这部手机 →</span></button>`).join('')}</div><footer>机型与软件均为网页重制体验，非原厂系统或官方应用。黑白屏手机不提供彩屏、Java 和互联网应用。</footer></section>`;}
function renderMonoWorkbench(){return `<section class="explore-workbench"><aside class="explore-library mono-library"><header class="explore-intro"><small>CLASSIC PHONE / ${phoneModels[phoneState.model].era}</small><h1>有些快乐，<br>一块黑白屏就够了。</h1><p>${phoneModels[phoneState.model].name} 保留短信、通讯录、原生贪吃蛇与计算器。没有 UC、QQ、Java、照片或视频。</p></header><div class="mono-function-list">${[['sms','✉','短信息'],['contacts','☷','通讯录'],['snake','▦','贪吃蛇'],['calculator','＋','计算器']].map(([id,i,t])=>`<button data-desk-open="${id}"><b>${i}</b><span>${t}</span><em>›</em></button>`).join('')}</div><div class="mono-device-note"><b>想逛网站、看漫画？</b><p>换一部彩屏或塞班手机，就能打开 UC、QQ、掌上杂志和软件下载。</p><button data-phone-picker>重新选择手机 →</button></div></aside><section class="home-phone-preview" aria-label="右侧复古手机"><div class="desk-phone-heading"><span><i></i> 黑白屏 · 原生功能</span><button data-phone-picker>换一部手机</button></div>${renderPhoneLab()}</section></section>`;}
function phoneMonoHomeMarkup(){return `<div class="mono-home"><div class="mono-network">中国移动</div><b class="mono-clock">20:04</b><small>${date.replaceAll('-',' / ')}</small><nav>${[['sms','信息'],['contacts','通讯录'],['snake','贪吃蛇'],['calculator','计算器']].map(([id,t],i)=>`<button class="${i===systemHomeIndex?'mono-selected':''}" data-desk-open="${id}">${i+1}　${t}　›</button>`).join('')}</nav><span>功能表　　通讯录</span></div>`;}
function phoneMonoSmsMarkup(){const rows=phoneSmsRows();if(smsView==='compose')return `<section class="mono-messages"><h3>编写信息</h3><label>收件人：106XXXX</label><textarea id="phone-sms-text" maxlength="160" aria-label="黑白屏短信内容">${escapeHTML(phoneState.draft)}</textarea><small>${phoneState.draft.length}/160</small><button data-sms-send>${smsSending?'正在发送…':'发送'}</button><button data-sms-view="inbox">返回</button><p>本机模拟，不产生短信费用。</p></section>`;if(smsView==='message'&&rows.length){const r=rows[Math.min(smsSelected,rows.length-1)];return `<section class="mono-messages"><h3>收到的信息</h3><small>106XXXX</small><p>${escapeHTML(r.reply)}</p><details><summary>已发送</summary><p>${escapeHTML(r.text)}</p></details><button data-sms-view="inbox">返回收件箱</button></section>`;}return `<section class="mono-messages"><h3>信息</h3><button data-sms-view="compose">✎ 编写信息</button>${rows.map((r,i)=>`<button data-sms-message="${i}">✉ ${escapeHTML(r.reply.slice(0,24))}…</button>`).join('')||'<p>暂无新信息</p>'}<small>仅文字短信 · 本机体验</small></section>`;}
function phoneContactsMarkup(){return `<section class="mono-contacts"><h3>通讯录</h3>${[['家里','138****0001'],['小夏','138****0002'],['同桌','138****0003']].map(([name,n])=>`<article><b>${name}</b><small>${n}</small></article>`).join('')}<p>虚构联系人 · 不提供拨打功能</p></section>`;}
function monoCalculatorKey(key){if(/^\d$/.test(key)){monoCalcValue=monoCalcFresh||monoCalcValue==='0'?key:(monoCalcValue+key).slice(0,12);monoCalcFresh=false;}else if(key==='C'){monoCalcValue='0';monoCalcLeft=null;monoCalcOperation=null;monoCalcFresh=true;}else if(key==='.'){if(monoCalcFresh){monoCalcValue='0';monoCalcFresh=false;}if(!monoCalcValue.includes('.'))monoCalcValue+='.';}else if(['+','−','×','÷'].includes(key)){monoCalcLeft=Number(monoCalcValue);monoCalcOperation=key;monoCalcFresh=true;}else if(key==='='&&monoCalcOperation){const n=Number(monoCalcValue),v=monoCalcOperation==='+'?monoCalcLeft+n:monoCalcOperation==='−'?monoCalcLeft-n:monoCalcOperation==='×'?monoCalcLeft*n:n===0?NaN:monoCalcLeft/n;monoCalcValue=Number.isFinite(v)?String(Number(v.toPrecision(10))):'错误';monoCalcOperation=null;monoCalcFresh=true;}return monoCalcValue;}
function phoneNativeCalculatorMarkup(){return `<section class="mono-calculator"><h3>计算器</h3><output aria-label="计算结果">${escapeHTML(monoCalcValue)}</output><div>${['7','8','9','÷','4','5','6','×','1','2','3','−','C','0','=','+'].map(k=>`<button data-native-calc="${k}">${k}</button>`).join('')}</div><small>数字键输入 · 确认键计算</small></section>`;}
function phoneQQMarkup(){const f=qqFriends.find(f=>f.id===qqChat);return `<section class="phone-qq"><header><b>QQ</b><span>${f?f.name:'我的好友'}<small>怀旧界面 · 离线体验</small></span><button data-qq-home aria-label="QQ好友列表">☰</button></header>${f?`<div class="qq-chat-sign">${f.sign}</div><div class="qq-chat-messages">${(qqMessages[f.id]||[{from:'friend',text:f.reply}]).map(m=>`<div class="qq-chat-line ${m.from==='me'?'qq-chat-me':''}"><small>${m.from==='me'?'我':f.name}</small><p>${escapeHTML(m.text)}</p></div>`).join('')}</div><form data-qq-chat-form><input name="message" maxlength="120" placeholder="和老朋友聊两句…" aria-label="QQ本机聊天内容" required><button>发送</button></form>`:`<div class="qq-self"><b>☺</b><span>旧日访客<small>● 在线　今天也有好心情。</small></span></div><nav><b>好友</b><span>群</span><span>消息</span></nav><div class="qq-group">▼ 我的好友 (${qqFriends.length})</div>${qqFriends.map(f=>`<button class="qq-friend" data-qq-friend="${f.id}"><b>${f.face}</b><span>${f.name}<small>${f.sign}</small></span><em>${f.status}</em></button>`).join('')}<div class="qq-offline-note">不连接真实 QQ，不收集账号密码。<br>联系人为虚构人物，对话仅保存在本机。</div>`}</section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-choose-phone],[data-phone-picker],[data-phone-picker-filter],[data-native-calc],[data-qq-friend],[data-qq-home]');if(!b)return;e.preventDefault();if(b.dataset.choosePhone){if(!Object.hasOwn(phoneModels,b.dataset.choosePhone))return;phoneState.model=b.dataset.choosePhone;phoneState.app='home';systemHomeIndex=0;deskEntered=true;savePhone();document.body.classList.remove('pocket-expanded','pocket-landscape');navigate({type:'home'},false);maybeDreamnetWelcome();return;}if(b.hasAttribute('data-phone-picker')){pocketJavaReleaseAll();deskEntered=false;phoneState.app='home';document.body.classList.remove('pocket-expanded','pocket-landscape');return navigate({type:'home'},false);}if(b.dataset.phonePickerFilter){phonePickerFilter=b.dataset.phonePickerFilter;return navigate({type:'home'},false);}if(b.dataset.nativeCalc){monoCalculatorKey(b.dataset.nativeCalc);return refreshPhone();}if(b.dataset.qqFriend){if(qqFriends.some(f=>f.id===b.dataset.qqFriend)){qqChat=b.dataset.qqFriend;refreshPhone();}return;}if(b.hasAttribute('data-qq-home')){qqChat=null;refreshPhone();}});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-qq-chat-form]'))return;e.preventDefault();const f=qqFriends.find(f=>f.id===qqChat),text=String(new FormData(e.target).get('message')||'').trim().slice(0,120);if(!f||!text)return;qqMessages[f.id]=[...(qqMessages[f.id]||[]),{from:'me',text},{from:'friend',text:f.reply}].slice(-20);try{localStorage.setItem('olddays-qq-demo',JSON.stringify(qqMessages));}catch{}refreshPhone();document.querySelector('[data-qq-chat-form]')?.scrollIntoView?.({block:'end'});});

document.addEventListener('keydown',e=>{if(!phoneSurfaceActive()||phoneState.app!=='calculator'||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.repeat)return;const k={Enter:'=',Escape:'C','-':'−','*':'×','/':'÷'}[e.key]||e.key;if(/^[0-9.=+]$/.test(k)||['C','−','×','÷'].includes(k)){e.preventDefault();monoCalculatorKey(k);refreshPhone();}});
